// Generated by Node crypto.scryptSync with its defaults and this fixed test salt.
const nodePasswordFixture = "AAECAwQFBgcICQoLDA0ODw==$dQ1U3LprmVknfbTKhdh3IKnaezpwwQ6kNPh1J+KsXH/M+RK+sQh0uX+Cw4bp8psbDFk5RrrODFY0YZ+Gbz5dkw=="

func testAuthStore(t *testing.T) *Store {
	t.Helper()
	store, err := NewStore(filepath.Join(t.TempDir(), "app.sqlite"), "test-admin-password")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { store.Close() })
	return store
}

func requireHTTPStatus(t *testing.T, err error, status int) {
	t.Helper()
	var failure *HTTPError
	if !errors.As(err, &failure) || failure.Status != status {
		t.Fatalf("expected HTTP %d, got %v", status, err)
	}
}

func TestPasswordNodeCompatibility(t *testing.T) {
	valid, err := verifyPassword("compatibility-密码123", nodePasswordFixture)
	if err != nil || !valid {
		t.Fatalf("existing Node password was not accepted: %v", err)
	}
	valid, err = verifyPassword("incorrect-password", nodePasswordFixture)
	if err != nil || valid {
		t.Fatalf("incorrect password result: %v, %v", valid, err)
	}
	for _, value := range []string{"short", strings.Repeat("x", 129), strings.Repeat("😀", 65)} {
		_, err := hashPassword(value)
		requireHTTPStatus(t, err, 400)
	}
	encoded, err := hashPassword(strings.Repeat("密", 128))
	if err != nil {
		t.Fatal("128 UTF-16 code units must remain valid", err)
	}
	valid, err = verifyPassword(strings.Repeat("密", 128), encoded)
	if err != nil || !valid {
		t.Fatal("Unicode password round trip failed", err)
	}
}

func TestStoreReadsExistingNodeSchemaAndPersists(t *testing.T) {
	filename := filepath.Join(t.TempDir(), "existing.sqlite")
	db, err := sql.Open("sqlite", filename)
	if err != nil {
		t.Fatal(err)
	}
	_, err = db.Exec(`CREATE TABLE users (id TEXT PRIMARY KEY,username TEXT NOT NULL COLLATE NOCASE UNIQUE,displayName TEXT NOT NULL,role TEXT NOT NULL,enabled INTEGER NOT NULL,passwordHash TEXT NOT NULL,createdAt INTEGER NOT NULL,updatedAt INTEGER NOT NULL);
		CREATE TABLE settings (key TEXT PRIMARY KEY,value TEXT NOT NULL);
		CREATE TABLE scores (id TEXT PRIMARY KEY,kind TEXT NOT NULL,at INTEGER NOT NULL,payload TEXT NOT NULL);`)
	if err != nil {
		t.Fatal(err)
	}
	_, err = db.Exec("INSERT INTO users VALUES (?,?,?,?,?,?,?,?)", "old-admin", "Admin", "原管理员", "super_admin", 1, nodePasswordFixture, 1700000000000, 1700000000001)
	if err != nil {
		t.Fatal(err)
	}
	if _, err = db.Exec("INSERT INTO settings VALUES (?,?)", "community", `{"aboutUs":"原社团内容","members":[]}`); err != nil {
		t.Fatal(err)
	}
	if _, err = db.Exec("INSERT INTO scores VALUES (?,?,?,?)", "old-score", "note", 1700000000000, `{"id":"old-score","player_id":"old-player","final_score":500,"at":1700000000000}`); err != nil {
		t.Fatal(err)
	}
	if err := db.Close(); err != nil {
		t.Fatal(err)
	}
	store, err := NewStore(filename, "")
	if err != nil {
		t.Fatal(err)
	}
	user, err := store.Authenticate(" \tADMIN\n", "compatibility-密码123")
	if err != nil || user == nil || user.ID != "old-admin" || user.DisplayName != "原管理员" {
		t.Fatalf("old login failed: %+v %v", user, err)
	}
	public, err := json.Marshal(user)
	if err != nil || strings.Contains(string(public), "password") {
		t.Fatal("public user must not expose password material", err)
	}
	community, err := store.GetValue("community", nil)
	if err != nil || asObject(community)["aboutUs"] != "原社团内容" {
		t.Fatalf("community changed: %v %v", community, err)
	}
	items, err := store.ScoreRows("note")
	if err != nil || len(items) != 1 || items[0]["id"] != "old-score" {
		t.Fatalf("score compatibility failed: %v %v", items, err)
	}
	if err := store.SetValue("game", Obj{"roundSeconds": 42}); err != nil {
		t.Fatal(err)
	}
	if err := store.Close(); err != nil {
		t.Fatal(err)
	}
	store, err = NewStore(filename, "")
	if err != nil {
		t.Fatal(err)
	}
	defer store.Close()
	value, err := store.GetValue("game", Obj{})
	if err != nil || number(asObject(value)["roundSeconds"]) != 42 {
		t.Fatalf("restart lost settings: %v %v", value, err)
	}
	var stored string
	if err := store.db.QueryRow("SELECT passwordHash FROM users WHERE id=?", "old-admin").Scan(&stored); err != nil || stored != nodePasswordFixture {
		t.Fatal("opening an existing database changed its password format", err)
	}
}

func TestStoreUserValidationAndInjection(t *testing.T) {
	store := testAuthStore(t)
	admin, err := store.Authenticate("admin", "test-admin-password")
	if err != nil || admin == nil {
		t.Fatal(err)
	}
	host, err := store.CreateUser(Obj{"username": "TestHost", "password": "host-password-one"})
	if err != nil || host.Role != "host" || !host.Enabled {
		t.Fatalf("create host failed: %+v %v", host, err)
	}
	_, err = store.CreateUser(Obj{"username": "testhost", "password": "host-password-one"})
	requireHTTPStatus(t, err, 409)
	_, err = store.CreateUser(Obj{"username": "invalid' OR 1=1", "password": "host-password-one"})
	requireHTTPStatus(t, err, 400)
	for _, name := range []string{"' OR 1=1 --", "admin'--", "admin'; DROP TABLE users;--", "missing-user"} {
		user, err := store.Authenticate(name, "wrong-password")
		if err != nil || user != nil {
			t.Fatalf("unexpected authentication for %q: %+v %v", name, user, err)
		}
	}
	if _, err := store.UpdateUser(host.ID, Obj{"enabled": false}, admin.ID); err != nil {
		t.Fatal(err)
	}
	user, err := store.Authenticate(host.Username, "host-password-one")
	if err != nil || user != nil {
		t.Fatal("disabled account authenticated", err)
	}
	if _, err := store.UpdateUser(host.ID, Obj{"enabled": true}, admin.ID); err != nil {
		t.Fatal(err)
	}
	if err := store.ResetPassword(host.ID, "host-password-two"); err != nil {
		t.Fatal(err)
	}
	user, err = store.Authenticate(host.Username, "host-password-one")
	if err != nil || user != nil {
		t.Fatal("old password still authenticated", err)
	}
	user, err = store.Authenticate(host.Username, "host-password-two")
	if err != nil || user == nil {
		t.Fatal("new password did not authenticate", err)
	}
	_, err = store.UpdateUser(admin.ID, Obj{"enabled": false}, admin.ID)
	requireHTTPStatus(t, err, 409)
	requireHTTPStatus(t, store.DeleteUser(admin.ID, admin.ID), 409)
	_, err = store.UpdateUser(admin.ID, Obj{"role": "host"}, admin.ID)
	requireHTTPStatus(t, err, 409)
	users, err := store.Users()
	if err != nil || len(users) != 2 {
		t.Fatalf("user table changed unexpectedly: %v %v", users, err)
	}
}

func TestStoreConcurrentAdminChangesKeepOneAdministrator(t *testing.T) {
	store := testAuthStore(t)
	first, _ := store.Authenticate("admin", "test-admin-password")
	second, err := store.CreateUser(Obj{"username": "other_admin", "password": "other-admin-password", "role": "super_admin"})
	if err != nil {
		t.Fatal(err)
	}
	var wg sync.WaitGroup
	errorsFound := make(chan error, 2)
	for _, id := range []string{first.ID, second.ID} {
		wg.Add(1)
		go func(id string) {
			defer wg.Done()
			_, err := store.UpdateUser(id, Obj{"role": "host"}, id)
			errorsFound <- err
		}(id)
	}
	wg.Wait()
	close(errorsFound)
	passed, refused := 0, 0
	for err := range errorsFound {
		if err == nil {
			passed++
		} else {
			requireHTTPStatus(t, err, 409)
			refused++
		}
	}
	if passed != 1 || refused != 1 {
		t.Fatalf("concurrent demotions: accepted=%d refused=%d", passed, refused)
	}
	users, err := store.Users()
	if err != nil {
		t.Fatal(err)
	}
	active := 0
	for _, user := range users {
		if user.Enabled && user.Role == "super_admin" {
			active++
		}
	}
	if active != 1 {
		t.Fatalf("remaining administrators: %d", active)
	}
}

func TestStoreSettingsCopiesAndScoreRetention(t *testing.T) {
	store := testAuthStore(t)
	fallback := Obj{"nested": Obj{"value": 1}}
	value, err := store.GetValue("absent", fallback)
	if err != nil {
		t.Fatal(err)
	}
	asObject(asObject(value)["nested"])["value"] = 9
	if number(asObject(fallback["nested"])["value"]) != 1 {
		t.Fatal("fallback settings were mutated")
	}
	tx, err := store.db.Begin()
	if err != nil {
		t.Fatal(err)
	}
	for index := 0; index < 2000; index++ {
		id := fmt.Sprintf("old-%04d", index)
		payload, _ := json.Marshal(Obj{"id": id, "score": index})
		if _, err := tx.Exec("INSERT INTO scores VALUES (?,?,?,?)", id, "note", index, string(payload)); err != nil {
			tx.Rollback()
			t.Fatal(err)
		}
	}
	if err := tx.Commit(); err != nil {
		t.Fatal(err)
	}
	input := Obj{"player_id": "new-player", "final_score": 900}
	added, err := store.AddScore("note", input)
	if err != nil || asString(added["id"]) == "" || number(added["at"]) <= 0 {
		t.Fatalf("new score: %v %v", added, err)
	}
	if _, mutated := input["id"]; mutated {
		t.Fatal("AddScore mutated caller input")
	}
	items, err := store.ScoreRows("note")
	if err != nil || len(items) != 2000 || items[0]["id"] != added["id"] {
		t.Fatalf("retention failed: count=%d err=%v", len(items), err)
	}
	if err := store.DeleteScore(asString(added["id"])); err != nil {
		t.Fatal(err)
	}
	if err := store.ClearScores("note"); err != nil {
		t.Fatal(err)
	}
	items, err = store.ScoreRows("note")
	if err != nil || len(items) != 0 {
		t.Fatal("score clear failed", err)
	}
}

func TestStoreCredentialSnapshotExpiresAfterReset(t *testing.T) {
	store := testAuthStore(t)
	admin, err := store.Authenticate("admin", "test-admin-password")
	if err != nil || admin == nil {
		t.Fatal(err)
	}
	// A future timestamp forces updates to advance even within the same clock tick.
	future := time.Now().Add(time.Minute).UnixMilli()
	if _, err := store.db.Exec("UPDATE users SET updatedAt=? WHERE id=?", future, admin.ID); err != nil {
		t.Fatal(err)
	}
	snapshot, err := store.Authenticate("admin", "test-admin-password")
	if err != nil || snapshot == nil {
		t.Fatal(err)
	}
	if err := store.ResetPassword(admin.ID, "replacement-password"); err != nil {
		t.Fatal(err)
	}
	current, err := store.User(admin.ID)
	if err != nil || current.UpdatedAt <= snapshot.UpdatedAt {
		t.Fatal("password reset left an authentication snapshot current", err)
	}
	changed, err := store.UpdateUser(admin.ID, Obj{"displayName": "changed"}, admin.ID)
	if err != nil || changed.UpdatedAt <= current.UpdatedAt {
		t.Fatal("user update did not advance credential revision", err)
	}
}

func TestPasswordWorkIsBounded(t *testing.T) {
	func() {
		passwordWork <- struct{}{}
		passwordWork <- struct{}{}
		defer func() { <-passwordWork; <-passwordWork }()
		_, err := verifyPassword("compatibility-密码123", nodePasswordFixture)
		requireHTTPStatus(t, err, 429)
		_, err = hashPassword("another-test-password")
		requireHTTPStatus(t, err, 429)
	}()
	valid, err := verifyPassword("compatibility-密码123", nodePasswordFixture)
	if err != nil || !valid {
		t.Fatal("password work did not resume after capacity was released", err)
	}
}
